/**
 * N6 — a correct server-side rejection must reach the owner as a specific, safe reason.
 *
 * The six contradictions are generated by the REAL create schema (the same validators the route runs), shaped as the route
 * answers them (400 + fieldErrors), and mapped by the same module the form uses. No internal name, schema phrase or stack may
 * appear; the first offending field (in form order) is the one to focus.
 */
import { describe, it, expect } from "vitest";
import { financialSnapshotCreateSchema } from "@/domain/owner-finance/validation";
import { parseOrThrow } from "@/lib/validation";
import { httpResponseErrorFromBody } from "@/lib/operator-safe-errors";
import { presentSnapshotFormError } from "@/domain/owner-finance/snapshot-form-errors";
import { FINANCE_CONFLICT_CODES } from "@/domain/owner-finance/snapshot-conflict";

const base = { periodStart: "2026-09-01", periodEnd: "2026-09-30", currency: "INR" };

/** What the route returns for a rejected body: status 400 and the validator's {path, message} pairs. */
function serverRejection(body: Record<string, unknown>) {
  try {
    parseOrThrow(financialSnapshotCreateSchema, { ...base, ...body });
  } catch (e) {
    const details = (e as { details?: { fieldErrors?: Array<{ path: string; message: string }> } }).details;
    return Object.assign(httpResponseErrorFromBody(400, { error: "Validation failed", fieldErrors: details?.fieldErrors ?? [] }), { responseBody: {} });
  }
  throw new Error("expected the schema to reject this body");
}

/** Everything the owner can read: the form line and each field line (never the machine keys). */
const ownerText = (p: { message: string; fieldMessages: Record<string, string> }) => [p.message, ...Object.values(p.fieldMessages)].join(" | ");

const INTERNAL = /periodEnd|periodStart|repeatCustomerCount|receivablesOverdue|payablesOverdue|salaryPayroll|b2cRevenue|b2bRevenue|fixedCosts|zod|schema|undefined|null|\bat \w+\.\w+\(|prisma|stack/i;

const CASES: Array<{ name: string; body: Record<string, unknown>; field: string; says: RegExp }> = [
  { name: "repeat customers > total customers", body: { customerCount: 10, repeatCustomerCount: 25 }, field: "repeatCustomerCount", says: /Repeat customers \(25\) cannot be more than total customers \(10\)/ },
  { name: "overdue receivables > total receivables", body: { receivables: 1000, receivablesOverdue: 1500 }, field: "receivablesOverdue", says: /Overdue receivables \(1500\) cannot be more than total receivables \(1000\)/ },
  { name: "overdue payables > total payables", body: { payables: 800, payablesOverdue: 900 }, field: "payablesOverdue", says: /Overdue payables \(900\) cannot be more than total payables \(800\)/ },
  { name: "fixed-cost components > total fixed costs", body: { fixedCosts: 1000, rent: 700, salaryPayroll: 600, utilities: 100 }, field: "fixedCosts", says: /Total fixed costs \(1000\) is less than the rent, payroll and utilities you entered \(1400\)/ },
  { name: "B2C + B2B revenue > total revenue", body: { revenue: 5000, b2cRevenue: 4000, b2bRevenue: 2000 }, field: "revenue", says: /Revenue \(5000\) is less than the consumer and business revenue you entered \(6000\)/ },
  { name: "reversed date range", body: { periodStart: "2026-09-30", periodEnd: "2026-09-01" }, field: "periodEnd", says: /The end of the period can't be before its start/ },
];

describe("N6 — the six contradictions are worded for the owner", () => {
  for (const c of CASES) {
    it(c.name, () => {
      const presented = presentSnapshotFormError(serverRejection(c.body), "create");
      expect(presented.kind).toBe("VALIDATION");
      expect(presented.fieldMessages[c.field]).toMatch(c.says);
      expect(presented.focusField).toBe(c.field);
      // Nothing technical, and "try saving again" is not the remedy for a contradiction.
      expect(ownerText(presented)).not.toMatch(INTERNAL);
      expect(presented.message).toMatch(/Nothing was saved/);
      expect(presented.message).toMatch(/correct/i);
      expect(presented.message).not.toMatch(/try (saving )?again/i);
      expect(presented.retryable).toBe(false);
    });
  }

  it("several problems at once: every field gets its own message and focus goes to the topmost field on the form", () => {
    const presented = presentSnapshotFormError(
      serverRejection({ periodStart: "2026-09-30", periodEnd: "2026-09-01", customerCount: 1, repeatCustomerCount: 5, revenue: 10, b2cRevenue: 20 }),
      "create"
    );
    expect(Object.keys(presented.fieldMessages).sort()).toEqual(["periodEnd", "repeatCustomerCount", "revenue"]);
    expect(presented.focusField).toBe("periodEnd");
    expect(presented.message).toMatch(/Some entries need correcting/);
  });

  it("a negative figure and an absurd figure get plain-language reasons built from the field's label", () => {
    const negative = presentSnapshotFormError(serverRejection({ revenue: -5 }), "create");
    expect(negative.fieldMessages.revenue).toBe("Revenue can't be negative. Enter 0 if there was none, or leave it blank if you don't know.");
    const huge = presentSnapshotFormError(serverRejection({ cashOnHand: 5e12 }), "create");
    expect(huge.fieldMessages.cashOnHand).toMatch(/Cash in hand is too large/);
  });

  it("an unknown path or an unrecognised schema phrase is never echoed — it falls back to a calm line", () => {
    const err = Object.assign(httpResponseErrorFromBody(400, { error: "Validation failed", fieldErrors: [{ path: "internalLedgerId", message: "Invalid input: expected string, received undefined" }] }), { responseBody: {} });
    const presented = presentSnapshotFormError(err, "create");
    expect(presented.fieldMessages).toEqual({});
    expect(ownerText(presented)).not.toMatch(/internalLedgerId|expected string|undefined/);
    expect(presented.message).toMatch(/Nothing was saved/);
  });

  it("an unreadable 400 with no field errors still says nothing was saved and what to check", () => {
    const presented = presentSnapshotFormError(httpResponseErrorFromBody(400, { error: "Validation failed" }), "create");
    expect(presented.kind).toBe("VALIDATION");
    expect(presented.message).toMatch(/Nothing was saved/);
    expect(presented.message).toMatch(/larger than its total/);
  });
});

describe("N6 — everything else stays generic and safe", () => {
  it("a 500 never shows the server's text, however technical it is", () => {
    const leak = "Invalid `prisma.ownerFinancialSnapshot.create()` invocation: Unique constraint failed on (business_id, period_start)\n    at Object.create (/var/task/node_modules/@prisma/client/runtime.js:1:1)";
    const presented = presentSnapshotFormError(Object.assign(httpResponseErrorFromBody(500, { error: leak }), { responseBody: { error: leak } }), "create");
    expect(presented.kind).toBe("SERVER");
    expect(presented.message).toMatch(/couldn't save this snapshot/);
    expect(presented.message).toMatch(/entries are still here/);
    expect(ownerText(presented)).not.toMatch(/prisma|Unique constraint|node_modules|business_id|period_start|runtime\.js/i);
    expect(presented.retryable).toBe(true);
  });

  it("a network failure (no response) is a retryable generic line", () => {
    const presented = presentSnapshotFormError(new TypeError("Failed to fetch"), "create");
    expect(presented.kind).toBe("OTHER");
    expect(presented.message).not.toMatch(/Failed to fetch|TypeError/);
    expect(presented.retryable).toBe(true);
  });

  it("401 and 403 are session / permission lines, not validation", () => {
    expect(presentSnapshotFormError(httpResponseErrorFromBody(401, {}), "create").kind).toBe("SESSION");
    expect(presentSnapshotFormError(httpResponseErrorFromBody(403, {}), "create").kind).toBe("PERMISSION");
  });
});

describe("N1 — conflicts are decided by machine code, never by message text", () => {
  it("create: FINANCE_PERIOD_EXISTS carries the existing snapshot id", () => {
    const body = { error: "A financial snapshot ... already exists. Amend it instead of creating a duplicate.", code: FINANCE_CONFLICT_CODES.PERIOD_EXISTS, snapshotId: "11111111-1111-4111-8111-111111111111" };
    const presented = presentSnapshotFormError(Object.assign(httpResponseErrorFromBody(409, body), { responseBody: body }), "create");
    expect(presented.kind).toBe("PERIOD_EXISTS");
    expect(presented.existingSnapshotId).toBe("11111111-1111-4111-8111-111111111111");
    expect(presented.message).toMatch(/Update that period/);
    expect(presented.message).not.toMatch(/409|conflict|amend/i);
  });

  it("amend: a superseded version is a stale-form line that asks the owner to review the latest figures", () => {
    const body = { error: "Snapshot a has already been superseded by b. Amend the latest version instead.", code: FINANCE_CONFLICT_CODES.SUPERSEDED, currentSnapshotId: "b" };
    const presented = presentSnapshotFormError(Object.assign(httpResponseErrorFromBody(409, body), { responseBody: body }), "amend");
    expect(presented.kind).toBe("STALE");
    expect(presented.message).toMatch(/nothing was changed/i);
    expect(ownerText(presented)).not.toMatch(/superseded|Snapshot a|\bb\b\./);
  });
});
